query GetTeams($filter: TeamFilter, $first: Int, $after: String) {
  teams(filter: $filter, first: $first, after: $after) {
    nodes {
      id
      name
      key
      description
      icon
      color
      cyclesEnabled
      createdAt
      updatedAt
      archivedAt
      organization {
        id
        name
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

